using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using WinShun.BatchRenamer;

static class CoreTests
{
    static int passed, failed;
    static string root, work;
    static void Equal<T>(T actual, T expected) { if (!Object.Equals(actual, expected)) throw new Exception("expected [" + expected + "], actual [" + actual + "]"); }
    static void True(bool value, string detail) { if (!value) throw new Exception(detail); }
    static void Throws(Action action) { bool threw = false; try { action(); } catch { threw = true; } if (!threw) throw new Exception("expected exception"); }
    static void Test(string name, Action action)
    {
        work = Path.Combine(root, (passed + failed + 1).ToString("D2")); Directory.CreateDirectory(work);
        try { action(); passed++; Console.WriteLine("PASS " + name); }
        catch (Exception ex) { failed++; Console.WriteLine("FAIL " + name + "\n" + ex); }
    }
    static string Item(string name, string content) { string path = Path.Combine(work, name); Directory.CreateDirectory(Path.GetDirectoryName(path)); File.WriteAllText(path, content); return path; }
    static string Dir(string name) { string path = Path.Combine(work, name); Directory.CreateDirectory(path); return path; }
    static FileEngine Engine() { return new FileEngine(Path.Combine(work, "data")); }
    static string Apply(string name, params Rule[] rules) { return ApplyAt(name, 0, false, "seed", rules); }
    static string ApplyAt(string name, int index, bool directory, string seed, params Rule[] rules)
    { return RuleEngine.Apply(name, rules, new NameContext { OriginalName = name, Parent = "相册", Key = name, Index = index, IsDirectory = directory, Date = new DateTime(2026, 10, 24), Seed = seed }); }
    static OperationPlan Rename(string[] paths, params Rule[] rules)
    { return Planner.Rename(paths.Select(x => new SourceItem { Path = x, IsDirectory = Directory.Exists(x) }).ToList(), rules, "seed", DateTime.Today); }
    static OperationPlan Mapping(Dictionary<string, string> map)
    {
        OperationPlan p = new OperationPlan();
        foreach (var pair in map) p.Entries.Add(new PlanEntry { Source = pair.Key, Destination = pair.Value, Name = Path.GetFileName(pair.Value), IsDirectory = Directory.Exists(pair.Key), Identity = Fs.Identity(pair.Key), Error = "" });
        Planner.Validate(p, true); return p;
    }
    static OperationPlan Create(string folder, bool directory, params string[] names)
    { return Planner.Create(folder, names, directory, new Rule[0], "seed", new DateTime(2026, 10, 24)); }
    static void NoTemps() { True(!Directory.EnumerateFileSystemEntries(work, ".wbr-*", SearchOption.AllDirectories).Any(), "temporary items remain"); }
    public static int Main()
    {
        Console.OutputEncoding = new System.Text.UTF8Encoding(false);
        root = Path.Combine(CommunityHost.PluginDirectory, "tests", ".runs", Guid.NewGuid().ToString("N")); Directory.CreateDirectory(root);
        Test("sequence padding and preserved extension", () => Equal(Apply("报告.txt", new Rule()), "报告_001.txt"));
        Test("sequence negative step and start", () => Equal(ApplyAt("a.txt", 2, false, "seed", new Rule { Start = 10, Step = -2, Digits = 3 }), "a_006.txt"));
        Test("ordered composition", () => Equal(Apply("OLD IMG.JPG", new Rule { Type = "Replace", Pattern = "OLD ", Replacement = "" }, new Rule { Type = "Case", Mode = "Lower" }, new Rule { Type = "Insert", Mode = "Prefix", Text = "相册_" }, new Rule()), "相册_img_001.JPG"));
        Test("rule order changes result", () => { Rule a = new Rule { Type = "Replace", Pattern = "A", Replacement = "B" }; Rule b = new Rule { Type = "Replace", Pattern = "B", Replacement = "C" }; Equal(Apply("A.txt", a, b), "C.txt"); Equal(Apply("A.txt", b, a), "B.txt"); });
        Test("extension-only lowercase", () => Equal(Apply("Hello.TXT", new Rule { Type = "Case", Target = "Extension", Mode = "Lower" }), "Hello.txt"));
        Test("full-name uppercase", () => Equal(Apply("hello.txt", new Rule { Type = "Case", Target = "FullName", Mode = "Upper" }), "HELLO.TXT"));
        Test("swap case", () => Equal(Apply("aBc.TXT", new Rule { Type = "Case", Mode = "Swap" }), "AbC.TXT"));
        Test("title case", () => Equal(Apply("hello WORLD.txt", new Rule { Type = "Case", Mode = "Title" }), "Hello World.txt"));
        Test("literal case insensitive replace keeps dollar literal", () => Equal(Apply("aAa.txt", new Rule { Type = "Replace", Pattern = "a", Replacement = "$1", IgnoreCase = true }), "$1$1$1.txt"));
        Test("insert Unicode text element", () => Equal(Apply("A😀B.txt", new Rule { Type = "Insert", Mode = "Position", Position = 2, Text = "中" }), "A😀中B.txt"));
        Test("insert negative offset", () => Equal(Apply("abc.txt", new Rule { Type = "Insert", Mode = "Position", Position = -1, Text = "_" }), "ab_c.txt"));
        Test("slice negative offset", () => Equal(Apply("abcdef.txt", new Rule { Type = "Slice", Mode = "Keep", Position = -3, Length = 2 }), "de.txt"));
        Test("slice remove", () => Equal(Apply("abcdef.txt", new Rule { Type = "Slice", Mode = "Remove", Position = 2, Length = 3 }), "abf.txt"));
        Test("slice out of range", () => Equal(Apply("abc.txt", new Rule { Type = "Slice", Mode = "Remove", Position = 100, Length = 3 }), "abc.txt"));
        Test("regex named captures", () => Equal(Apply("IMG_20261024.txt", new Rule { Type = "Regex", Pattern = @"^IMG_(?<year>\d{4})(?<tail>\d{4})$", Replacement = "${year}-${tail}" }), "2026-1024.txt"));
        Test("regex extract and no-match", () => { Rule r = new Rule { Type = "Regex", Mode = "Extract", Pattern = @"(\d+)", Replacement = "$1" }; Equal(Apply("ab123cd.txt", r), "123.txt"); Equal(Apply("abc.txt", r), "abc.txt"); });
        Test("invalid regex blocks preview", () => Throws(() => Apply("x", new Rule { Type = "Regex", Pattern = "[" })));
        Test("regex timeout bounded", () => Throws(() => Apply(new string('a', 500) + "!", new Rule { Type = "Regex", Pattern = "(a+)+$", Replacement = "" })));
        Test("random stable until seed changes", () => { Rule r = new Rule { Type = "Random", Length = 24 }; string a = ApplyAt("a.txt", 0, false, "seed1", r); Equal(a, ApplyAt("a.txt", 0, false, "seed1", r)); True(a != ApplyAt("a.txt", 0, false, "seed2", r), "seed did not change result"); });
        Test("random different files and requested alphabet", () => { Rule r = new Rule { Type = "Random", Mode = "Replace", Length = 32, Charset = "AB" }; string a = Apply("a.txt", r); True(a.Substring(0, 32).All(x => x == 'A' || x == 'B'), "alphabet mismatch"); True(a != Apply("b.txt", r), "file random values match"); });
        Test("random invalid alphabet rejected", () => Throws(() => Apply("x", new Rule { Type = "Random", Charset = "A" })));
        Test("template original current extension date parent", () => Equal(Apply("photo.jpg", new Rule { Type = "Case", Mode = "Upper" }, new Rule { Type = "Template", Text = "{name}_{original}_{ext}_{parent}_{n:000}_{date:yyyyMMdd}" }), "PHOTO_photo_jpg_相册_001_20261024.jpg"));
        Test("disabled rule skipped", () => Equal(Apply("a.txt", new Rule { Enabled = false }), "a.txt"));
        Test("dotfile and extensionless handling", () => { Equal(Apply(".gitignore", new Rule()), ".gitignore_001"); Equal(Apply("README", new Rule()), "README_001"); });
        Test("folder extension rules skipped", () => Equal(ApplyAt("folder.name", 0, true, "seed", new Rule { Type = "Case", Target = "Extension", Mode = "Upper" }), "folder.name"));
        Test("invalid Windows names", () => { foreach (string n in new[] { "", " ", ".", "..", "CON", "NUL.txt", "COM1.doc", "LPT².txt", "CON .txt", "x.", "x ", "a/b", "a\\b", "a:b", "a?b" }) Throws(() => Fs.ValidateName(n)); Fs.ValidateName("CONSOLE.txt"); });
        Test("basic rename preserves content and undo", () => { string a = Item("a.txt", "payload"); string id = Fs.Identity(a); FileEngine e = Engine(); e.Execute(Rename(new[] { a }, new Rule())); string b = Path.Combine(work, "a_001.txt"); Equal(File.ReadAllText(b), "payload"); Equal(Fs.Identity(b), id); new FileEngine(Path.Combine(work, "data")).UndoLast(); Equal(File.ReadAllText(a), "payload"); NoTemps(); });
        Test("case-only rename and undo", () => { string a = Item("Mixed.txt", "case"); FileEngine e = Engine(); e.Execute(Rename(new[] { a }, new Rule { Type = "Case", Target = "FullName", Mode = "Upper" })); True(Directory.GetFiles(work).Select(Path.GetFileName).Contains("MIXED.TXT"), "case not updated"); e.UndoLast(); True(Directory.GetFiles(work).Select(Path.GetFileName).Contains("Mixed.txt"), "case not restored"); });
        Test("two file names swap without overwrite", () => { string a = Item("a.txt", "A"), b = Item("b.txt", "B"); FileEngine e = Engine(); e.Execute(Mapping(new Dictionary<string, string> { { a, b }, { b, a } })); Equal(File.ReadAllText(a), "B"); Equal(File.ReadAllText(b), "A"); e.UndoLast(); Equal(File.ReadAllText(a), "A"); Equal(File.ReadAllText(b), "B"); NoTemps(); });
        Test("three-name cycle", () => { string a = Item("a", "A"), b = Item("b", "B"), c = Item("c", "C"); Engine().Execute(Mapping(new Dictionary<string, string> { { a, b }, { b, c }, { c, a } })); Equal(File.ReadAllText(a), "C"); Equal(File.ReadAllText(b), "A"); Equal(File.ReadAllText(c), "B"); });
        Test("nested parent and child rename then undo", () => { string file = Item("old-parent\\old-child\\old-file.txt", "nested"); string parent = Path.Combine(work, "old-parent"), child = Path.Combine(parent, "old-child"); FileEngine e = Engine(); e.Execute(Rename(new[] { parent, child, file }, new Rule { Type = "Replace", Pattern = "old", Replacement = "new" })); Equal(File.ReadAllText(Path.Combine(work, "new-parent\\new-child\\new-file.txt")), "nested"); e.UndoLast(); Equal(File.ReadAllText(file), "nested"); NoTemps(); });
        Test("case-only nested directories", () => { string file = Item("Parent\\Child\\Mixed.txt", "nested-case"); FileEngine e = Engine(); e.Execute(Rename(new[] { Path.Combine(work, "Parent"), Path.Combine(work, "Parent\\Child"), file }, new Rule { Type = "Case", Target = "FullName", Mode = "Lower" })); Equal(File.ReadAllText(Path.Combine(work, "parent\\child\\mixed.txt")), "nested-case"); e.UndoLast(); Equal(File.ReadAllText(file), "nested-case"); });
        Test("directory swap preserves descendants", () => { string a = Dir("a"), b = Dir("b"); Item("a\\inside.txt", "A"); Item("b\\inside.txt", "B"); FileEngine e = Engine(); e.Execute(Mapping(new Dictionary<string, string> { { a, b }, { b, a } })); Equal(File.ReadAllText(Path.Combine(a, "inside.txt")), "B"); e.UndoLast(); Equal(File.ReadAllText(Path.Combine(a, "inside.txt")), "A"); });
        Test("unchanged child follows renamed parent", () => { string file = Item("old\\child.txt", "follow"); FileEngine e = Engine(); e.Execute(Rename(new[] { Path.Combine(work, "old"), file }, new Rule { Type = "Replace", Pattern = "old", Replacement = "new" })); Equal(File.ReadAllText(Path.Combine(work, "new\\child.txt")), "follow"); e.UndoLast(); Equal(File.ReadAllText(file), "follow"); });
        Test("existing target prevents all changes", () => { string a = Item("a.txt", "A"), b = Item("b.txt", "B"); OperationPlan p = Rename(new[] { a }, new Rule { Type = "Insert", Target = "FullName", Mode = "Replace", Text = "b.txt" }); True(!p.Valid, "collision not detected"); Throws(() => Engine().Execute(p)); Equal(File.ReadAllText(a), "A"); Equal(File.ReadAllText(b), "B"); });
        Test("duplicate destination prevents batch", () => { string a = Item("a.txt", "A"), b = Item("b.txt", "B"); OperationPlan p = Rename(new[] { a, b }, new Rule { Type = "Insert", Mode = "Replace", Text = "same" }); True(!p.Valid && p.Entries.All(x => x.Error.Length > 0), "duplicate not flagged on all rows"); Throws(() => Engine().Execute(p)); });
        Test("source replaced after preview rejected", () => { string a = Item("a.txt", "A"); OperationPlan p = Rename(new[] { a }, new Rule()); File.Move(a, a + ".backup"); Item("a.txt", "replacement"); Throws(() => Engine().Execute(p)); Equal(File.ReadAllText(a), "replacement"); });
        Test("target introduced after preview rejected", () => { string a = Item("a.txt", "A"); OperationPlan p = Rename(new[] { a }, new Rule()); Item("a_001.txt", "external"); Throws(() => Engine().Execute(p)); Equal(File.ReadAllText(a), "A"); Equal(File.ReadAllText(Path.Combine(work, "a_001.txt")), "external"); });
        Test("phase-one failure rolls back", () => { string a = Item("a", "A"), b = Item("b", "B"); FileEngine e = Engine(); int moves = 0; e.BeforeMove = (x, y) => { if (++moves == 2) throw new IOException("injected"); }; Throws(() => e.Execute(Rename(new[] { a, b }, new Rule()))); Equal(File.ReadAllText(a), "A"); Equal(File.ReadAllText(b), "B"); Equal(e.Pending().Count, 0); NoTemps(); });
        Test("phase-two failure rolls back nested moves", () => { string file = Item("old\\old.txt", "rollback"); FileEngine e = Engine(); int moves = 0; e.BeforeMove = (x, y) => { if (++moves == 4) throw new IOException("injected-final"); }; Throws(() => e.Execute(Rename(new[] { Path.Combine(work, "old"), file }, new Rule { Type = "Replace", Pattern = "old", Replacement = "new" }))); Equal(File.ReadAllText(file), "rollback"); Equal(e.Pending().Count, 0); NoTemps(); });
        Test("locked file produces no mutations", () => { string a = Item("a.txt", "locked"); OperationPlan p = Rename(new[] { a }, new Rule()); using (FileStream locked = new FileStream(a, FileMode.Open, FileAccess.ReadWrite, FileShare.None)) Throws(() => Engine().Execute(p)); Equal(File.ReadAllText(a), "locked"); NoTemps(); });
        Test("batch creates files with date and numbers", () => { string folder = Dir("output"); FileEngine e = Engine(); e.Execute(Create(folder, false, "文档_{n:000}_{date:yyyyMMdd}.txt", "文档_{n:000}_{date:yyyyMMdd}.txt")); True(File.Exists(Path.Combine(folder, "文档_001_20261024.txt")), "first missing"); True(File.Exists(Path.Combine(folder, "文档_002_20261024.txt")), "second missing"); e.UndoLast(); Equal(Directory.GetFiles(folder).Length, 0); NoTemps(); });
        Test("batch creates folders then undoes", () => { string folder = Dir("output"); FileEngine e = Engine(); e.Execute(Create(folder, true, "第一项", "第二项")); Equal(Directory.GetDirectories(folder).Length, 2); e.UndoLast(); Equal(Directory.GetDirectories(folder).Length, 0); NoTemps(); });
        Test("creation supports combined rules", () => { string folder = Dir("output"); OperationPlan p = Planner.Create(folder, new[] { "HELLO.TXT", "WORLD.TXT" }, false, new[] { new Rule { Type = "Case", Target = "FullName", Mode = "Lower" }, new Rule() }, "seed", DateTime.Today); Engine().Execute(p); True(File.Exists(Path.Combine(folder, "hello_001.txt")), "first composite missing"); True(File.Exists(Path.Combine(folder, "world_002.txt")), "second composite missing"); });
        Test("creation existing path not overwritten", () => { string folder = Dir("output"); string existing = Item("output\\a", "keep"); OperationPlan p = Create(folder, false, "a"); True(!p.Valid, "create collision missed"); Throws(() => Engine().Execute(p)); Equal(File.ReadAllText(existing), "keep"); });
        Test("create path traversal rejected", () => { string folder = Dir("output"); foreach (string name in new[] { "..\\escape", "../escape", "C:\\escape", "a:b", "CON" }) True(!Create(folder, false, name).Valid, "invalid create accepted " + name); });
        Test("creation duplicate case-insensitive names", () => True(!Create(Dir("output"), false, "A.txt", "a.TXT").Valid, "case collision missed"));
        Test("creation failure removes only its own files", () => { string folder = Dir("output"); Item("output\\keep.txt", "keep"); FileEngine e = Engine(); int moves = 0; e.BeforeMove = (x, y) => { if (++moves == 2) throw new IOException("injected create failure"); }; Throws(() => e.Execute(Create(folder, false, "a", "b", "c"))); Equal(Directory.GetFiles(folder).Length, 1); Equal(File.ReadAllText(Path.Combine(folder, "keep.txt")), "keep"); NoTemps(); });
        Test("undo creation refuses nonempty files as a whole", () => { string folder = Dir("output"); FileEngine e = Engine(); e.Execute(Create(folder, false, "a", "b")); File.WriteAllText(Path.Combine(folder, "b"), "user content"); Throws(() => e.UndoLast()); True(File.Exists(Path.Combine(folder, "a")), "empty sibling was removed"); Equal(File.ReadAllText(Path.Combine(folder, "b")), "user content"); });
        Test("undo creation refuses nonempty folder", () => { string folder = Dir("output"); FileEngine e = Engine(); e.Execute(Create(folder, true, "a", "b")); Item("output\\a\\keep.txt", "keep"); Throws(() => e.UndoLast()); True(Directory.Exists(Path.Combine(folder, "b")), "empty sibling was removed"); });
        Test("undo creation refuses replacement identity", () => { string folder = Dir("output"); FileEngine e = Engine(); e.Execute(Create(folder, false, "a")); string path = Path.Combine(folder, "a"); File.Move(path, Path.Combine(folder, "saved")); using (File.Create(path)) { } Throws(() => e.UndoLast()); True(File.Exists(path), "replacement deleted"); });
        Test("undo rename refuses occupied original", () => { string a = Item("a.txt", "A"); FileEngine e = Engine(); e.Execute(Rename(new[] { a }, new Rule())); Item("a.txt", "external"); Throws(() => e.UndoLast()); Equal(File.ReadAllText(a), "external"); Equal(File.ReadAllText(Path.Combine(work, "a_001.txt")), "A"); });
        Test("undo rename allows in-place content edits", () => { string a = Item("a.txt", "A"); FileEngine e = Engine(); e.Execute(Rename(new[] { a }, new Rule())); File.WriteAllText(Path.Combine(work, "a_001.txt"), "edited"); e.UndoLast(); Equal(File.ReadAllText(a), "edited"); });
        Test("recovery handles crash after move before done flag", () => { string a = Item("a", "recover"), temp = Path.Combine(work, ".wbr-simulated"); string id = Fs.Identity(a); Transaction tx = new Transaction { Id = "crash", Kind = "Rename", State = "Running", CreatedAt = DateTime.UtcNow.ToString("o") }; tx.Moves.Add(new MoveRecord { From = a, To = temp, Identity = id, Done = false }); Json.AtomicWrite(Path.Combine(work, "data\\transactions\\crash.json"), tx); File.Move(a, temp); Engine().RecoverPending(); Equal(File.ReadAllText(a), "recover"); Equal(Engine().Pending().Count, 0); NoTemps(); });
        Test("recovery handles already reversed unmarked move", () => { string a = Item("a", "recover"); Transaction tx = new Transaction { Id = "crash", Kind = "Rename", State = "RecoveryNeeded", CreatedAt = DateTime.UtcNow.ToString("o") }; tx.Moves.Add(new MoveRecord { From = a, To = a + ".tmp", Identity = Fs.Identity(a), Done = true }); Json.AtomicWrite(Path.Combine(work, "data\\transactions\\crash.json"), tx); Engine().RecoverPending(); Equal(File.ReadAllText(a), "recover"); });
        Test("pending journal blocks new operation", () => { string a = Item("a", "A"); Transaction tx = new Transaction { Id = "crash", Kind = "Rename", State = "Running", CreatedAt = DateTime.UtcNow.ToString("o") }; Json.AtomicWrite(Path.Combine(work, "data\\transactions\\crash.json"), tx); Throws(() => Engine().Execute(Rename(new[] { a }, new Rule()))); Equal(File.ReadAllText(a), "A"); });
        Test("recovery never overwrites occupied source", () => { string a = Item("a", "A"), temp = a + ".tmp"; string id = Fs.Identity(a); File.Move(a, temp); Item("a", "external"); Transaction tx = new Transaction { Id = "crash", Kind = "Rename", State = "Running", CreatedAt = DateTime.UtcNow.ToString("o") }; tx.Moves.Add(new MoveRecord { From = a, To = temp, Identity = id, Done = true }); Json.AtomicWrite(Path.Combine(work, "data\\transactions\\crash.json"), tx); Throws(() => Engine().RecoverPending()); Equal(File.ReadAllText(a), "external"); Equal(File.ReadAllText(temp), "A"); });
        Test("persisted preset round trip", () => { Preset p = new Preset { Version = 1, Rules = new List<Rule> { new Rule { Type = "Regex", Pattern = "(中文)", Replacement = "$1_", IgnoreCase = true }, new Rule() } }; string path = Path.Combine(work, "preset.json"); Json.AtomicWrite(path, p); Preset restored = Json.Decode<Preset>(File.ReadAllText(path)); Equal(restored.Rules.Count, 2); Equal(restored.Rules[0].Pattern, "(中文)"); True(restored.Rules[0].IgnoreCase, "preset flag lost"); Json.AtomicWrite(path, restored); });
        Test("operation lock prevents parallel writers", () => { string a = Item("a", "A"); Directory.CreateDirectory(Path.Combine(work, "data")); using (FileStream locked = new FileStream(Path.Combine(work, "data\\operations.lock"), FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.None)) Throws(() => Engine().Execute(Rename(new[] { a }, new Rule()))); Equal(File.ReadAllText(a), "A"); });
        Test("append-only journal recovers moved file", () => { string a = Item("a", "journal"), temp = Path.Combine(work, ".wbr-crash"); string id = Fs.Identity(a); Transaction tx = new Transaction { Id = "crash", Kind = "Rename", State = "Running", CreatedAt = DateTime.UtcNow.ToString("o") }; string log = Path.Combine(work, "data\\transactions\\crash.json"); Json.AtomicWrite(log, tx); File.WriteAllText(log + "l", Json.Encode(new JournalEvent { Sequence = 1, Type = "Move", Move = new MoveRecord { From = a, To = temp, Identity = id } }) + "\n"); File.Move(a, temp); Engine().RecoverPending(); Equal(File.ReadAllText(a), "journal"); Equal(Engine().Pending().Count, 0); NoTemps(); });
        Test("torn final journal record is safely discarded", () => { string a = Item("a", "torn"), temp = Path.Combine(work, ".wbr-crash"); string id = Fs.Identity(a); Transaction tx = new Transaction { Id = "crash", Kind = "Rename", State = "Running", CreatedAt = DateTime.UtcNow.ToString("o") }; string log = Path.Combine(work, "data\\transactions\\crash.json"); Json.AtomicWrite(log, tx); File.WriteAllText(log + "l", Json.Encode(new JournalEvent { Sequence = 1, Type = "Move", Move = new MoveRecord { From = a, To = temp, Identity = id } }) + "\n{\"Sequence\":"); File.Move(a, temp); Engine().RecoverPending(); Equal(File.ReadAllText(a), "torn"); Equal(Engine().History()[0].State, "RolledBack"); True(File.ReadAllText(log + "l").EndsWith("\n"), "torn tail retained"); NoTemps(); });
        Test("append-only creation log recovers new item", () => { string folder = Dir("output"), temp = Item("output\\.wbr-create", ""), dest = Path.Combine(folder, "created.txt"); string id = Fs.Identity(temp); Transaction tx = new Transaction { Id = "crash", Kind = "Create", State = "Running", CreatedAt = DateTime.UtcNow.ToString("o") }; tx.Entries.Add(new PlanEntry { Source = "", Destination = dest, Name = "created.txt" }); string log = Path.Combine(work, "data\\transactions\\crash.json"); Json.AtomicWrite(log, tx); File.WriteAllText(log + "l", String.Join("\n", new[] { Json.Encode(new JournalEvent { Sequence = 1, Type = "PrepareCreate", Index = 0, Value = temp }), Json.Encode(new JournalEvent { Sequence = 2, Type = "Created", Index = 0, Value = id }), Json.Encode(new JournalEvent { Sequence = 3, Type = "Move", Move = new MoveRecord { From = temp, To = dest, Identity = id } }) }) + "\n"); File.Move(temp, dest); Engine().RecoverPending(); Equal(Directory.GetFiles(folder).Length, 0); NoTemps(); });
        Test("interrupted creation undo finishes empty deletion", () => { string folder = Dir("output"); FileEngine e = Engine(); Transaction original = e.Execute(Create(folder, false, "a")); string from = Path.Combine(folder, "a"), temp = Path.Combine(folder, ".wbr-undo"); string id = Fs.Identity(from); File.Move(from, temp); Transaction undo = new Transaction { Id = "undo-crash", Kind = "UndoCreateStage", State = "DeletePending", CreatedAt = DateTime.UtcNow.ToString("o"), UndoOf = original.Id }; undo.Entries.Add(new PlanEntry { Source = from, Destination = temp, Identity = id }); Json.AtomicWrite(Path.Combine(work, "data\\transactions\\undo-crash.json"), undo); e.RecoverPending(); Equal(Directory.GetFiles(folder).Length, 0); True(e.LastUndoable() == null, "original still undoable"); Equal(e.Pending().Count, 0); });
        Test("cancelled preview stops immediately", () => { string a = Item("a", "A"); var cancel = new System.Threading.CancellationTokenSource(); cancel.Cancel(); Throws(() => Planner.Rename(new[] { new SourceItem { Path = a } }, new[] { new Rule() }, "seed", DateTime.Today, cancel.Token)); Throws(() => Planner.Create(Dir("output"), new[] { "a" }, false, new[] { new Rule() }, "seed", DateTime.Today, cancel.Token)); cancel.Dispose(); });
        Test("metadata folder cannot rename its own parent", () => { Directory.CreateDirectory(Path.Combine(work, "data")); string parent = work; OperationPlan p = Mapping(new Dictionary<string, string> { { parent, parent + "-renamed" } }); Throws(() => Engine().Execute(p)); True(Directory.Exists(work), "journal parent moved"); });
        Test("bundled presets deserialize and execute", () => { string presets = Path.Combine(CommunityHost.PluginDirectory, "presets"); foreach (string path in Directory.GetFiles(presets, "*.json")) { Preset p = Json.Decode<Preset>(File.ReadAllText(path)); Equal(p.Version, 1); string result = Apply("20261024_报告.JPG", p.Rules.ToArray()); Fs.ValidateName(result); if (Path.GetFileName(path) == "正则日期整理.json") Equal(result, "2026-10-24_报告.JPG"); } });
        Console.WriteLine("RESULT " + passed + " passed, " + failed + " failed");
        if (failed == 0) Directory.Delete(root, true); else Console.WriteLine("Fixtures retained: " + root);
        return failed == 0 ? 0 : 1;
    }
}
